insert into public.freelance_level5_module6_assessment(position,prompt,option_a,option_b,option_c,option_d,correct_option,explanation) values
(1,'¿Qué caracteriza a una prioridad estratégica real?','Que todas las iniciativas permanezcan activas','Que exista una elección explícita y también una renuncia o secuencia','Que tenga el presupuesto más alto','Que nunca pueda cambiar','B','Priorizar implica asignar capacidad limitada y decidir qué no se ejecuta ahora.'),
(2,'¿Qué evalúa CARTERA antes de mantener activa una iniciativa?','Solo entusiasmo del equipo','Contribución, evidencia, capacidad, riesgo y dependencias','Solo ventas históricas','Cantidad de reuniones','B','CARTERA evita acumular proyectos sin fundamento ni capacidad.'),
(3,'Una iniciativa prometedora carece de evidencia suficiente. ¿Qué acción es más responsable?','Inventar ROI para justificarla','Desplegarla globalmente','Convertirla en un experimento limitado con hipótesis y criterio de revisión','Descartarla siempre','C','La incertidumbre puede gestionarse mediante aprendizaje controlado, no mediante cifras inventadas.'),
(4,'¿Qué es costo de oportunidad en gestión de portafolio?','Un gasto contable obligatorio','El valor de la alternativa a la que se renuncia al usar capacidad en otra iniciativa','Una comisión comercial','Un costo que debe ignorarse','B','Toda asignación consume recursos que dejan de estar disponibles para otras opciones.'),
(5,'¿Para qué sirve PRIORIZA?','Para cambiar prioridades todos los días','Para reasignar recursos con evidencia, restricciones, umbrales y trazabilidad','Para evitar decisiones','Para garantizar forecasts','B','El marco permite adaptación disciplinada sin reaccionar al ruido.'),
(6,'¿Cuándo conviene reasignar capacidad?','Ante cualquier variación pequeña','Cuando nueva evidencia cambia materialmente valor, riesgo, urgencia o capacidad disponible','Solo al cierre del año','Nunca después de aprobar un plan','B','Los planes deben adaptarse ante cambios materiales, no ante ruido.'),
(7,'¿Qué error representa seguir financiando una iniciativa solo porque ya se invirtió mucho?','Sesgo de costo hundido','Diversificación','Capacidad excedente','Mínimo privilegio','A','La inversión pasada no debe justificar consumo futuro si la evidencia cambió.'),
(8,'Si falta un dato clave para decidir, el director debe:','Inventar un promedio','Ocultar la incertidumbre','Marcar el dato como desconocido y decidir si requiere evidencia adicional o un experimento limitado','Duplicar la meta','C','La trazabilidad exige distinguir hechos, supuestos e incertidumbre.'),
(9,'¿Cuál es el propósito principal de CONTINUA?','Predecir todos los incidentes posibles','Mantener funciones críticas y recuperar operación mediante preparación y límites claros','Compartir credenciales por prevención','Eliminar controles durante una crisis','B','La continuidad prepara capacidad mínima y recuperación sin abandonar seguridad.'),
(10,'En continuidad, ¿qué significa mínimo privilegio?','Dar acceso administrativo a todos los suplentes','Conceder solo el acceso necesario mediante el proceso formal y auditable','Compartir una contraseña común','Eliminar permisos temporalmente','B','La contingencia no justifica accesos excesivos ni credenciales compartidas.'),
(11,'Un responsable crítico queda indisponible. ¿Qué debe ocurrir primero si existe un plan?','Improvisar un nuevo organigrama','Activar la suplencia y operación mínima definidas, escalando lo que exceda autoridad','Dar permisos totales al equipo','Suspender toda actividad','B','La preparación previa permite continuidad controlada y escalamiento apropiado.'),
(12,'¿Cuándo termina correctamente una respuesta de continuidad?','Cuando vuelve el responsable original','Cuando se oculta el incidente','Después de recuperar, realizar retrospectiva y registrar acciones preventivas','Al terminar la primera reunión','C','La recuperación madura incorpora aprendizaje para reducir riesgo futuro.')
